using System;
class PauseInputGateTests {
 static int Checks;static void Check(bool result,bool expected,string reason){if(result!=expected)throw new Exception(reason);Checks++;}
 public static void Main(){var gate=new PauseInputGate();Check(gate.Read(0,0,true,true,false,false,false),false,"initial sample primes input");Check(gate.Read(1,1,true,true,true,false,false),true,"P1 pauses");Check(gate.Read(1,1,true,true,true,true,false),false,"same frame cannot toggle twice");Check(gate.Read(2,2,true,true,true,false,false),false,"held Start does not repeat");Check(gate.Read(3,3,true,true,true,true,false),true,"P2 resumes while P1 still holds Start");Check(gate.Read(4,4,true,true,false,false,false),false,"release");Check(gate.Read(5,5,true,true,true,true,false),true,"simultaneous press toggles only once");Check(gate.Read(6,6,true,true,false,false,false),false,"release both");Check(gate.Read(7,7,true,true,false,true,false),true,"P2 pauses");Check(gate.Read(8,8,true,true,false,false,false),false,"release P2");Check(gate.Read(9,9,true,true,true,false,false),true,"P1 resumes P2 pause");gate.Transition(10,10);Check(gate.Read(10,10,true,true,false,false,true),false,"native transition consumes current frame");Check(gate.Read(11,10.1f,true,true,false,false,true),false,"transition cooldown");Check(gate.Read(12,11,true,true,false,false,true),false,"held Escape cannot reopen after cooldown");Check(gate.Read(13,12,true,true,false,false,false),false,"Escape released");Check(gate.Read(14,13,true,true,false,false,true),true,"fresh Escape toggles");Check(gate.Read(15,14,false,true,false,false,false),false,"unfocused game ignores commands");Check(gate.Read(16,15,true,true,true,false,false),false,"focus regain primes held input");Check(gate.Read(17,16,true,true,true,false,false),false,"held input stays consumed");Check(gate.Read(18,17,true,true,false,false,false),false,"release after focus");Check(gate.Read(19,18,true,true,true,false,false),true,"new press after focus");Check(gate.Read(20,19,true,false,false,true,false),false,"upgrade menu blocks pause");Check(gate.Read(21,20,true,true,false,true,false),false,"held blocked press does not leak into gameplay");gate.Reset();Check(gate.Read(22,21,true,true,true,true,true),false,"new run primes all held buttons");Console.WriteLine("PASS: "+Checks+" pause/resume edge, ownership, focus, cooldown and menu cases.");}
}
